const snippets={"Python": ["from typing import List", "", "class Solution:", "", "    def canFinish(self, numCourses: int, prerequisites: List[List[int]]) -> bool:", "        g = [[] for _ in range(numCourses)]", "        indeg = [0] * numCourses", "        for (a, b) in prerequisites:", "            g[b].append(a)", "            indeg[a] += 1", "        q = [i for (i, x) in enumerate(indeg) if x == 0]", "        for i in q:", "            numCourses -= 1", "            for j in g[i]:", "                indeg[j] -= 1", "                if indeg[j] == 0:", "                    q.append(j)", "        return numCourses == 0"], "Java": ["import java.util.*;", "class Solution {", "    public boolean canFinish(int numCourses, int[][] prerequisites) {", "        List<Integer>[] g = new List[numCourses];", "        Arrays.setAll(g, k -> new ArrayList<>());", "        int[] indeg = new int[numCourses];", "        for (var p : prerequisites) {", "            int a = p[0], b = p[1];", "            g[b].add(a);", "            ++indeg[a];", "        }", "        Deque<Integer> q = new ArrayDeque<>();", "        for (int i = 0; i < numCourses; ++i) {", "            if (indeg[i] == 0) {", "                q.offer(i);", "            }", "        }", "        while (!q.isEmpty()) {", "            int i = q.poll();", "            --numCourses;", "            for (int j : g[i]) {", "                if (--indeg[j] == 0) {", "                    q.offer(j);", "                }", "            }", "        }", "        return numCourses == 0;", "    }", "}"]};
